//! License texts built into the binary and shown from About, so they travel
//! with every copy of the launcher, self-updated ones included.

use slint::{ModelRc, SharedString, VecModel};

use crate::LicenseLine;

const OWN: &str = include_str!("../../../LICENSE");
/// Generated by scripts/licenses.sh.
const THIRD_PARTY: &str = include_str!("../../../THIRD-PARTY-LICENSES.md");

/// One entry per paragraph (the list only lays out what is on screen), line
/// breaks kept. Markdown headings become highlighted entries, code fences
/// are dropped.
pub fn lines() -> ModelRc<LicenseLine> {
    let mut entries = Vec::new();
    let mut paragraph = String::new();
    for line in OWN.lines().chain([""]).chain(THIRD_PARTY.lines()) {
        let line = line.trim_end();
        if line.starts_with("```") {
            continue;
        }
        if let Some(heading) = line.strip_prefix('#') {
            flush(&mut paragraph, &mut entries);
            entries.push(LicenseLine {
                text: SharedString::from(heading.trim_start_matches('#').trim_start()),
                heading: true,
            });
        } else if line.is_empty() {
            flush(&mut paragraph, &mut entries);
        } else {
            if !paragraph.is_empty() {
                paragraph.push('\n');
            }
            paragraph.push_str(line);
        }
    }
    flush(&mut paragraph, &mut entries);
    ModelRc::new(VecModel::from(entries))
}

fn flush(paragraph: &mut String, entries: &mut Vec<LicenseLine>) {
    if !paragraph.is_empty() {
        entries.push(LicenseLine {
            text: SharedString::from(paragraph.as_str()),
            heading: false,
        });
        paragraph.clear();
    }
}

#[cfg(test)]
mod tests {
    use slint::Model;

    #[test]
    fn own_license_first_then_every_third_party_one() {
        let entries: Vec<_> = super::lines().iter().collect();
        assert_eq!(entries[0].text, "MIT License");
        assert!(entries.iter().all(|e| !e.text.contains("```")));
        assert!(
            entries
                .iter()
                .any(|e| e.heading && e.text == "Slint Royalty-free License 2.0")
        );
    }
}
